-- Vcare: the old app's daily KPI checklist -> Daily Checklist (25 Sep 2026).
-- Read-only from the source on 25 Sep 2026: 78 days, 2925 person-days,
-- 20 Jun - 29 Nov 2025, five points (present, on leave, on time, WhatsApp
-- update, dress code). Only people who have an Atlas login are brought over.
-- Guarded: no-op on a database without Vcare data; a re-run adds nothing.

-- The five points, for the Vcare branch, if it has none yet.
WITH vc AS (
  SELECT "storeId" FROM "Complaint" WHERE "legacyRef" IS NOT NULL
   GROUP BY "storeId" ORDER BY count(*) DESC LIMIT 1
)
INSERT INTO "StaffChecklistItem" (id, "storeId", key, label, sort, "isActive", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, vc."storeId", v.key, v.label, v.sort, true, now(), now()
  FROM (VALUES ('attendance', 'Present', 0), ('leave', 'On leave', 1), ('in_time', 'On time', 2),
               ('whatsapp_update', 'WhatsApp update sent', 3), ('in_dress_code', 'In dress code', 4)) AS v(key, label, sort)
  CROSS JOIN vc
ON CONFLICT ("storeId", key) DO NOTHING;

-- The history.
WITH vc AS (
  SELECT "storeId" FROM "Complaint" WHERE "legacyRef" IS NOT NULL
   GROUP BY "storeId" ORDER BY count(*) DESC LIMIT 1
)
INSERT INTO "StaffChecklistEntry" (id, "storeId", "userId", "workDate", "values", "legacyRef", "createdAt", "updatedAt")
